        foreach ($groups as $group => $keys) {
            foreach (['en', 'ar', 'ur', 'eu'] as $code) {
                foreach ($keys as $key => $langValues) {
                    if (!isset($langValues[$code])) continue;
                    DB::table('translations')->updateOrInsert(
                        ['group' => $group, 'key' => $key, 'language_code' => $code],
                        ['value' => $langValues[$code], 'created_at' => now(), 'updated_at' => now()]
                    );
                }
            }
        }
